<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api'
import type { Category, Faq, Page } from '../types'
import { useAuthStore } from '../stores/auth'
const auth=useAuthStore(),categories=ref<Category[]>([]),rows=ref<Faq[]>([]),total=ref(0),loading=ref(false),drawer=ref(false),categoryDrawer=ref(false),editing=ref<Faq|null>(null)
const query=reactive({keyword:'',categoryId:'',status:'',page:1,pageSize:20}),form=reactive({categoryId:'',title:'',question:'',answer:'',summary:'',keywords:'',top:false}),catForm=reactive({id:'',name:'',sortOrder:0,status:'ENABLED',version:0})
async function load(){loading.value=true;try{categories.value=await api.get('/faq-categories');const p=await api.get<Page<Faq>>('/faqs',query);rows.value=p.items;total.value=p.total}catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}}
function edit(row?:Faq){editing.value=row||null;Object.assign(form,row?{categoryId:row.categoryId,title:row.title,question:row.question,answer:row.answer,summary:row.summary,keywords:row.keywords,top:row.top}:{categoryId:categories.value[0]?.id||'',title:'',question:'',answer:'',summary:'',keywords:'',top:false});drawer.value=true}
async function save(){try{if(editing.value)await api.patch(`/faqs/${editing.value.id}`,form,editing.value.version);else await api.post('/faqs',form);ElMessage.success('保存成功');drawer.value=false;load()}catch(e){ElMessage.error((e as Error).message)}}
async function status(row:Faq,target:string){try{await ElMessageBox.confirm(`确认将该 FAQ 设为 ${target}？`,'状态确认');await api.post(`/faqs/${row.id}/${target==='PUBLISHED'?'publish':'archive'}`,{},row.version);ElMessage.success('状态已更新');load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
function editCategory(c?:Category){Object.assign(catForm,c?{id:c.id,name:c.name,sortOrder:c.sortOrder,status:c.status,version:c.version}:{id:'',name:'',sortOrder:0,status:'ENABLED',version:0});categoryDrawer.value=true}
async function saveCategory(){try{const b={name:catForm.name,sortOrder:catForm.sortOrder,status:catForm.status};if(catForm.id)await api.patch(`/faq-categories/${catForm.id}`,b,catForm.version);else await api.post('/faq-categories',b);ElMessage.success('分类已保存');categoryDrawer.value=false;load()}catch(e){ElMessage.error((e as Error).message)}}
async function removeCategory(c:Category){try{await ElMessageBox.confirm('仅空分类可以删除，确定继续？','删除分类',{type:'warning'});await api.delete(`/faq-categories/${c.id}`,c.version);load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
onMounted(load)
</script>
<template><div><div class="page-heading"><div><h2>FAQ 管理</h2><p>维护常见问题内容、分类和发布状态</p></div><div v-if="auth.isAdmin"><el-button @click="categoryDrawer=true">分类管理</el-button><el-button type="primary" @click="edit()">新建 FAQ</el-button></div></div><div class="panel toolbar"><el-input v-model="query.keyword" clearable placeholder="标题、问题或关键词"/><el-select v-model="query.categoryId" clearable placeholder="全部分类" style="width:170px"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select v-model="query.status" clearable placeholder="全部状态" style="width:150px"><el-option v-for="s in ['DRAFT','PUBLISHED','ARCHIVED']" :key="s" :label="s" :value="s"/></el-select><el-button type="primary" @click="load">查询</el-button></div><div class="panel table-panel"><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="title" label="标题" min-width="220"/><el-table-column prop="question" label="问题" min-width="260" show-overflow-tooltip/><el-table-column prop="hotCount" label="热度" width="80"/><el-table-column label="状态" width="120"><template #default="{row}"><el-tag>{{row.status}}</el-tag></template></el-table-column><el-table-column prop="updatedAt" label="更新时间" width="190"/><el-table-column v-if="auth.isAdmin" label="操作" width="230" fixed="right"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button v-if="row.status!=='PUBLISHED'" link type="success" @click="status(row,'PUBLISHED')">发布</el-button><el-button v-if="row.status!=='ARCHIVED'" link type="warning" @click="status(row,'ARCHIVED')">归档</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.page" layout="total,prev,pager,next" :total="total" @change="load"/></div></div><el-drawer v-model="drawer" :title="editing?'编辑 FAQ':'新建 FAQ'" size="min(620px,96vw)"><el-form label-position="top" style="padding:0 22px"><el-form-item label="分类"><el-select v-model="form.categoryId" style="width:100%"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="用户问题"><el-input v-model="form.question" type="textarea" :rows="3"/></el-form-item><el-form-item label="标准答案"><el-input v-model="form.answer" type="textarea" :rows="7"/></el-form-item><el-form-item label="摘要"><el-input v-model="form.summary"/></el-form-item><el-form-item label="关键词"><el-input v-model="form.keywords" placeholder="多个关键词以逗号分隔"/></el-form-item><el-checkbox v-model="form.top">置顶</el-checkbox><el-button type="primary" style="width:100%;margin-top:22px" @click="save">保存草稿</el-button></el-form></el-drawer><el-drawer v-model="categoryDrawer" title="FAQ 分类" size="min(520px,96vw)"><div style="padding:0 20px"><el-table :data="categories"><el-table-column prop="name" label="名称"/><el-table-column prop="sortOrder" label="排序" width="80"/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="操作" width="120"><template #default="{row}"><el-button link @click="editCategory(row)">编辑</el-button><el-button link type="danger" @click="removeCategory(row)">删除</el-button></template></el-table-column></el-table><el-divider/><el-form inline><el-input v-model="catForm.name" placeholder="分类名称" style="width:180px"/><el-input-number v-model="catForm.sortOrder" :min="0" style="width:100px"/><el-select v-model="catForm.status" style="width:120px"><el-option label="启用" value="ENABLED"/><el-option label="禁用" value="DISABLED"/></el-select><el-button type="primary" @click="saveCategory">{{catForm.id?'更新':'新增'}}</el-button><el-button v-if="catForm.id" @click="editCategory()">取消</el-button></el-form></div></el-drawer></div></template>
